import{_ as t,o as i,c as o,ag as a}from"./chunks/framework.DQQHyi2x.js";const h=JSON.parse('{"title":"Settings Gap Update — Implementation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"plans/2026-04-10-settings-gap-update-plan.md","filePath":"plans/2026-04-10-settings-gap-update-plan.md"}'),s={name:"plans/2026-04-10-settings-gap-update-plan.md"};function l(n,e,d,r,c,p){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="settings-gap-update-—-implementation-plan" tabindex="-1">Settings Gap Update — Implementation Plan <a class="header-anchor" href="#settings-gap-update-—-implementation-plan" aria-label="Permalink to &quot;Settings Gap Update — Implementation Plan&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Claude-deck&#39;s settings editor (last updated 2026-03-20) is missing settings that Claude Code has added since: Auto Mode, Plugins/Marketplaces, Sandbox filesystem controls, and 14 new hook events. The SettingsEditor.tsx is also 1,090 lines (exceeds 800-line max). This plan closes the gaps and fixes the file size.</p><p><strong>Design spec:</strong> <code>docs/superpowers/specs/2026-04-10-settings-gap-update-design.md</code></p><hr><h2 id="phase-0-split-settingseditor-pure-refactor" tabindex="-1">Phase 0: Split SettingsEditor (Pure Refactor) <a class="header-anchor" href="#phase-0-split-settingseditor-pure-refactor" aria-label="Permalink to &quot;Phase 0: Split SettingsEditor (Pure Refactor)&quot;">​</a></h2><p>Extract into <code>frontend/src/features/config/settings/</code> module:</p><ol><li>Create <code>settings/field-components.tsx</code> — move SwitchSetting, NumberSetting, SelectSetting, TextSetting, AttributionField, ListEditor, KeyValueEditor (~335 lines)</li><li>Create <code>settings/constants.ts</code> — move MODEL_OPTIONS, PERMISSION_MODE_OPTIONS, UPDATE_CHANNEL_OPTIONS, LOGIN_METHOD_OPTIONS, EFFORT_LEVEL_OPTIONS, TEAMMATE_MODE_OPTIONS</li><li>Create <code>settings/cards/*.tsx</code> — extract each card (Authentication, General, Memory, Sandbox, Permissions, McpServers, Attribution, Ui, EnvVars, HooksSecurity, Advanced) into its own file</li><li>Create <code>settings/SettingsEditor.tsx</code> — orchestrator with state management, scope selector, save button, renders card components via standard <code>SettingsCardProps</code></li><li>Create <code>settings/index.ts</code> — re-export SettingsEditor</li><li>Update <code>ConfigViewerPage.tsx</code> import path</li><li>Delete old <code>SettingsEditor.tsx</code></li><li>Verify: <code>npm run lint &amp;&amp; npm run build</code>, manual test all scopes</li></ol><p><strong>Critical files:</strong></p><ul><li><code>frontend/src/features/config/SettingsEditor.tsx</code> (source, 1090 lines)</li><li><code>frontend/src/features/config/ConfigViewerPage.tsx</code> (import update)</li></ul><hr><h2 id="phase-1-auto-mode-card-80-lines" tabindex="-1">Phase 1: Auto Mode Card (~80 lines) <a class="header-anchor" href="#phase-1-auto-mode-card-80-lines" aria-label="Permalink to &quot;Phase 1: Auto Mode Card (~80 lines)&quot;">​</a></h2><ol><li>Add <code>cards/AutoModeCard.tsx</code> with scope guard (<code>scope !== &#39;project&#39;</code>): <ul><li><code>autoMode.environment</code> (ListEditor)</li><li><code>autoMode.allow</code> (ListEditor)</li><li><code>autoMode.soft_deny</code> (ListEditor)</li><li><code>permissions.disableAutoMode</code> (SwitchSetting)</li></ul></li><li>Add <code>{ value: &#39;auto&#39;, label: &#39;Auto&#39; }</code> to PERMISSION_MODE_OPTIONS in constants.ts</li><li>Import and render AutoModeCard in SettingsEditor after PermissionsCard</li><li>Verify: lint, build, manual test</li></ol><hr><h2 id="phase-2-plugin-management-card-120-lines" tabindex="-1">Phase 2: Plugin Management Card (~120 lines) <a class="header-anchor" href="#phase-2-plugin-management-card-120-lines" aria-label="Permalink to &quot;Phase 2: Plugin Management Card (~120 lines)&quot;">​</a></h2><ol><li>Add <code>ObjectArrayEditor</code> component to <code>field-components.tsx</code> (~50 lines) for <code>{name, url}</code> pairs</li><li>Add <code>cards/PluginManagementCard.tsx</code>: <ul><li><code>enabledPlugins</code> (ListEditor)</li><li><code>extraKnownMarketplaces</code> (ObjectArrayEditor)</li><li>Managed-only: <code>blockedMarketplaces</code>, <code>pluginTrustMessage</code>, <code>strictKnownMarketplaces</code></li></ul></li><li>Import and render in SettingsEditor after McpServersCard</li><li>Verify: lint, build, manual test</li></ol><hr><h2 id="phase-3-sandbox-filesystem-rules-40-lines" tabindex="-1">Phase 3: Sandbox Filesystem Rules (~40 lines) <a class="header-anchor" href="#phase-3-sandbox-filesystem-rules-40-lines" aria-label="Permalink to &quot;Phase 3: Sandbox Filesystem Rules (~40 lines)&quot;">​</a></h2><ol><li>Add to existing <code>cards/SandboxCard.tsx</code>: <ul><li><code>sandbox.filesystem.allowRead</code> (ListEditor, gitignore patterns)</li><li><code>sandbox.filesystem.denyRead</code> (ListEditor)</li><li>Managed-only: <code>sandbox.filesystem.allowManagedReadPathsOnly</code>, <code>sandbox.network.allowManagedDomainsOnly</code></li></ul></li><li>Verify: lint, build, manual test</li></ol><hr><h2 id="phase-4-hook-event-editor-550-lines-across-2-files" tabindex="-1">Phase 4: Hook Event Editor (~550 lines across 2 files) <a class="header-anchor" href="#phase-4-hook-event-editor-550-lines-across-2-files" aria-label="Permalink to &quot;Phase 4: Hook Event Editor (~550 lines across 2 files)&quot;">​</a></h2><ol><li>Extend <code>frontend/src/types/hooks.ts</code>: <ul><li>Add 14 new events to HookEvent union</li><li>Add metadata entries to HOOK_EVENTS array</li><li>Add <code>if</code> and <code>shell</code> fields to Hook interface</li></ul></li><li>Add hook event constants to <code>settings/constants.ts</code> (HOOK_EVENT_GROUPS, HANDLER_TYPE_OPTIONS, SHELL_OPTIONS)</li><li>Add <code>cards/HookEntryForm.tsx</code> (~350 lines) — dialog form with: <ul><li>Event selector (grouped by category)</li><li>Handler type selector (command/http/prompt/agent)</li><li>Common fields (matcher, if, timeout, statusMessage, once)</li><li>Conditional fields per handler type</li></ul></li><li>Add <code>cards/HookEventEditorCard.tsx</code> (~200 lines) — card showing: <ul><li>Grouped event list with handler counts</li><li>Collapsible per-event sections</li><li>Add/Edit/Delete actions opening HookEntryForm</li></ul></li><li>Import and render in SettingsEditor</li><li>Verify: lint, build, full hook editor workflow test</li></ol><hr><h2 id="verification-after-all-phases" tabindex="-1">Verification (after all phases) <a class="header-anchor" href="#verification-after-all-phases" aria-label="Permalink to &quot;Verification (after all phases)&quot;">​</a></h2><ol><li><code>cd frontend &amp;&amp; npm run lint</code> — no warnings</li><li><code>cd frontend &amp;&amp; npm run build</code> — clean build</li><li>Start dev servers, navigate to Settings Editor</li><li>Test each scope (user, project, local, managed)</li><li>Test save round-trip for new settings</li><li>Test hook editor: add hook → configure → save → verify in raw JSON</li><li>Cross-check against official docs — all user-facing settings editable</li></ol>',25)])])}const g=t(s,[["render",l]]);export{h as __pageData,g as default};
